<template><div class="space-y-4 p-4"><div><p class="text-[10px] font-bold uppercase tracking-widest text-indigo-500">Cebu Marketplace</p><h1 class="mt-1 text-xl font-bold text-slate-800">Verified supplier listings</h1></div><form class="m-card space-y-3" @submit.prevent="load"><input v-model="q" class="m-input" placeholder="Search products and services" /><button class="m-btn-primary">Search</button></form><NuxtLink v-for="item in items" :key="item.id" :to="`/marketplace/${item.id}`" class="m-card block"><div class="flex justify-between gap-3"><p class="text-sm font-semibold text-slate-800">{{ item.title }}</p><span class="status-pill bg-emerald-50 text-emerald-600">{{ item.status }}</span></div><p class="mt-3 text-lg font-bold text-indigo-600">{{ money(item.price_minor, item.currency) }}</p></NuxtLink><p v-if="error" class="m-card text-sm text-red-600">{{ error }}</p></div></template>
<script setup lang="ts">
const { listPublicListings } = useCommerce(); const q = ref(''); const items = ref<any[]>([]); const error = ref(''); const money = (value?: number, currency = 'EUR') => value == null ? 'Request price' : new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(value / 100); async function load() { try { items.value = (await listPublicListings({ q: q.value })).items } catch (e: any) { error.value = e?.data?.detail || e?.message } } onMounted(load)
</script>
